func errConflict(primary string, secondaries []string, usageFlags []string) string {
	var msg string
	if len(secondaries) == 1 {
		msg = fmt.Sprintf("error: the argument '%s' cannot be used with '%s'\n\n", primary, secondaries[0])
	} else {
		msg = fmt.Sprintf("error: the argument '%s' cannot be used with:\n", primary)
		for _, s := range secondaries {
			msg += fmt.Sprintf("  %s\n", s)
		}
		msg += "\n"
	}
	usage := fmt.Sprintf("Usage: %s", binName())
	for _, f := range usageFlags {
		usage += " " + f
	}
	usage += " <URL>\n"
	msg += usage + "\nFor more information, try '--help'.\n"
	fmt.Fprint(os.Stderr, msg)
	return ""
}

