}

func getSingle(values map[string][]string, display string) (string, bool) {
	v, ok := values[display]
	if !ok || len(v) == 0 {
		return "", false
	}
	return v[0], true
}

func getMulti(values map[string][]string, display string) []string {
	return values[display]
}

func hasFlag(values map[string][]string, display string) bool {
	_, ok := values[display]
	return ok
}

func parseNToInt(s string) int {
	trimmed := strings.TrimSpace(s)
	last := trimmed[len(trimmed)-1]
	if last == 'k' || last == 'K' {
		prefix := trimmed[:len(trimmed)-1]
		f, _ := strconv.ParseFloat(prefix, 64)
		return int(f * 1000)
	} else if last == 'm' || last == 'M' {
		prefix := trimmed[:len(trimmed)-1]
		f, _ := strconv.ParseFloat(prefix, 64)
		return int(f * 1000000)
	} else {
		n, _ := strconv.Atoi(trimmed)
		return n
	}
}

func parseInt(s string) int {
	// Handles leading +?
	if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	n, _ := strconv.Atoi(s)
	return n
}

func parseFloatVal(s string) float64 {
	f, _ := strconv.ParseFloat(s, 64)
	return f
}

func parseDurationToNs(s string) int64 {
	if s == "0" {
		return 0
	}
	trimmed := strings.TrimSpace(s)
	// Parse humantime to ns (simplified, assumes valid)
	return humantimeToNs(trimmed)
}

func humantimeToNs(s string) int64 {
	// Parse sequence of number+unit, sum
	var total float64 // use float for 1.5s etc., then convert to ns? Need precise? For 1.5s => 1500000000 ns. Use float then int64.
	i := 0
	n := len(s)
	totalNs := int64(0)
	for i < n {
		for i < n && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i >= n {
			break
		}
		startNum := i
		for i < n && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i < n && s[i] == '.' {
			i++
			for i < n && s[i] >= '0' && s[i] <= '9' {
				i++
			}
		}
		numStr := s[startNum:i]
		num, _ := strconv.ParseFloat(numStr, 64)
		for i < n && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		unitStart := i
		for i < n && s[i] != ' ' && s[i] != '\t' && !(s[i] >= '0' && s[i] <= '9') {
			// Handle UTF-8 for µ? s[i] is byte, µ is 2 bytes (C2 B5 or CE BC). Our loop on bytes will treat each byte separately, but that's okay for unit detection? For "µs" (3 bytes: C2 B5 73 or CE BC 73), our loop will consume all 3 bytes as part of unit (since none are digit/space). Good. Then unit string will be "µs" (with correct bytes). Good.
			i++
		}
		unit := s[unitStart:i]
		mult := unitToNs(unit)
		totalNs += int64(num * float64(mult))
		_ = total
	}
	return totalNs
}

func unitToNs(u string) int64 {
	switch u {
	case "ns", "nsec", "nsecs", "nanos", "nanosec", "nanosecs", "nanosecond", "nanoseconds":
		return 1
	case "us", "µs", "μs", "usec", "usecs", "micro", "micros", "microsec", "microsecs", "microsecond", "microseconds":
		return 1000
	case "ms", "msec", "msecs", "millis", "millisec", "millisecs", "millisecond", "milliseconds":
		return 1000000
	case "s", "sec", "secs", "second", "seconds":
		return 1000000000
	case "m", "min", "mins", "minute", "minutes":
		return 60 * 1000000000
	case "h", "hour", "hours":
		return 3600 * 1000000000
	case "d", "day", "days":
		return 24 * 3600 * 1000000000
	case "w", "week", "weeks":
		return 7 * 24 * 3600 * 1000000000
	case "M", "month", "months":
		return 30 * 24 * 3600 * 1000000000
	case "y", "year", "years":
		return 365 * 24 * 3600 * 1000000000
	default:
		return 1
