package main

import (
	"fmt"
	"net"
	"os"
	"strings"
	"time"
)

func matchesConnectTo(targetURL string, entries []string) bool {
	scheme, hostPort, _ := splitURL(targetURL)
	// Parse target host and port (with defaults)
	var targetHost, targetPort string
	if strings.HasPrefix(hostPort, "[") {
		closeIdx := strings.Index(hostPort, "]")
		if closeIdx == -1 {
			return false
		}
		targetHost = hostPort[:closeIdx+1]
		after := hostPort[closeIdx+1:]
		if strings.HasPrefix(after, ":") {
			targetPort = after[1:]
		} else {
			if scheme == "http" {
				targetPort = "80"
			} else if scheme == "https" {
				targetPort = "443"
			} else {
				targetPort = ""
			}
		}
	} else {
		if idx := strings.LastIndex(hostPort, ":"); idx != -1 {
			targetHost = hostPort[:idx]
			targetPort = hostPort[idx+1:]
		} else {
			targetHost = hostPort
			if scheme == "http" {
				targetPort = "80"
			} else if scheme == "https" {
				targetPort = "443"
			} else {
				targetPort = ""
			}
		}
	}
	targetHostLower := strings.ToLower(targetHost)
	for _, e := range entries {
		parts := splitConnectTo(e)
		var reqHost, reqPort string
		if len(parts) == 4 {
			reqHost = parts[0]
			reqPort = parts[1]
		} else if len(parts) > 4 {
			n := len(parts)
			reqPort = parts[n-3]
			reqHost = strings.Join(parts[:n-3], ":")
		} else {
			continue
		}
		if strings.ToLower(reqHost) == targetHostLower && reqPort == targetPort {
			return true
		}
