func getTimeUnit(cfgTimeUnit *string, avgSec *float64) (string, string, float64) {
  // Returns (unitNameForDisplay, unitKey, multiplier to convert seconds to unit)
  // unitKey is one of ns,us,ms,s,m,h (for internal? Actually display names: ns,us,ms,sec,min,hr)
  // multiplier: seconds * multiplier = value in unit (e.g., seconds*1e9 for ns)
  if cfgTimeUnit != nil {
