    case "m":
      return "min", "m", 1.0/60.0
    case "h":
      return "hr", "h", 1.0/3600.0
    }
  }
  // Auto based on avg
  if avgSec == nil || math.IsNaN(*avgSec) {
    return "ns", "ns", 1e9
  }
  avg := *avgSec
  if avg < 1e-6 {
    return "ns", "ns", 1e9
  } else if avg < 1e-3 {
    return "us", "us", 1e6
  } else if avg < 1.0 {
    return "ms", "ms", 1e3
