func formatJSONOutput(cfg *Config, totalSec float64, successRate, slowest, fastest, average *float64, reqPerSec float64, totalData int64, sizePerReq *float64, sizePerSec float64, histKeys []string, histCounts []int, p10, p25, p50, p75, p90, p95, p99, p999, p9999 *float64, rpsMean, rpsStddev, rpsMax, rpsMin, rpsP10, rpsP25, rpsP50, rpsP75, rpsP90, rpsP95, rpsP99, rpsP999, rpsP9999 *float64, dialAvg, dialFast, dialSlow, dnsAvg, dnsFast, dnsSlow *float64, statusDist map[int]int, errDist map[string]int, successes []ReqResult) string {
  histMap := make(map[string]int)
  for i, k := range histKeys {
    histMap[k] = histCounts[i]
  }
  statusMap := make(map[string]int)
  for k, v := range statusDist {
    statusMap[strconv.Itoa(k)] = v
  }
  out := jsonOutput{
    Summary: jsonSummary{
      SuccessRate: successRate,
      Total: totalSec,
      Slowest: slowest,
      Fastest: fastest,
      Average: average,
      RequestsPerSec: reqPerSec,
      TotalData: totalData,
      SizePerRequest: sizePerReq,
      SizePerSec: sizePerSec,
    },
    ResponseTimeHistogram: histMap,
    LatencyPercentiles: jsonPercentiles{P10: p10, P25: p25, P50: p50, P75: p75, P90: p90, P95: p95, P99: p99, P999: p999, P9999: p9999},
