      DNSLookup: jsonDetail{Average: dnsAvg, Fastest: dnsFast, Slowest: dnsSlow},
    },
    StatusCodeDistribution: statusMap,
    ErrorDistribution: errDist,
  }
  if cfg.StatsBreakdown {
    var succDurs, notSuccDurs []float64
    for _, s := range successes {
      if s.Status >= 200 && s.Status < 300 {
        succDurs = append(succDurs, s.Duration.Seconds())
      } else {
        notSuccDurs = append(notSuccDurs, s.Duration.Seconds())
      }
    }
    sKeys, sCounts := computeHistogram(succDurs)
    sMap := make(map[string]int)
    for i, k := range sKeys {
      sMap[k] = sCounts[i]
