    nMap := make(map[string]int)
    for i, k := range nKeys {
      nMap[k] = nCounts[i]
    }
    out.ResponseTimeHistogramSuccessful = sMap
    out.ResponseTimeHistogramNotSuccessful = nMap
    // Percentiles for succ/not
    sort.Float64s(succDurs)
    sort.Float64s(notSuccDurs)
    pctSucc := func(p float64) *float64 {
      if len(succDurs) == 0 {
        return nil
      }
      idx := int(float64(len(succDurs)) * p)
      if idx >= len(succDurs) {
        idx = len(succDurs) - 1
      }
      v := succDurs[idx]
      return &v
    }
    pctNot := func(p float64) *float64 {
      if len(notSuccDurs) == 0 {
        return nil
      }
      idx := int(float64(len(notSuccDurs)) * p)
      if idx >= len(notSuccDurs) {
        idx = len(notSuccDurs) - 1
      }
      v := notSuccDurs[idx]
      return &v
    }
    out.LatencyPercentilesSuccessful = &jsonPercentiles{P10: pctSucc(0.10), P25: pctSucc(0.25), P50: pctSucc(0.50), P75: pctSucc(0.75), P90: pctSucc(0.90), P95: pctSucc(0.95), P99: pctSucc(0.99), P999: pctSucc(0.999), P9999: pctSucc(0.9999)}
    out.LatencyPercentilesNotSuccessful = &jsonPercentiles{P10: pctNot(0.10), P25: pctNot(0.25), P50: pctNot(0.50), P75: pctNot(0.75), P90: pctNot(0.90), P95: pctNot(0.95), P99: pctNot(0.99), P999: pctNot(0.999), P9999: pctNot(0.9999)}
  }
  data, _ := json.MarshalIndent(out, "", "  ")
  return string(data)
}
