func formatTextOutput(cfg *Config, totalSec float64, totalDur time.Duration, successRate, slowest, fastest, average *float64, reqPerSec float64, totalData int64, sizePerReq *float64, sizePerSec float64, histKeys []string, histCounts []int, durations []float64, p10, p25, p50, p75, p90, p95, p99, p999, p9999 *float64, dialAvg, dialFast, dialSlow, dnsAvg, dnsFast, dnsSlow *float64, statusDist map[int]int, errDist map[string]int, successes []ReqResult) string {
  unitDisplay, _, mult := getTimeUnit(cfg.TimeUnit, average)
  var b strings.Builder
  b.WriteString("Summary:\n")
  if successRate == nil {
    b.WriteString("  Success rate:\tNaN%\n")
  } else {
    fmt.Fprintf(&b, "  Success rate:\t%.2f%%\n", *successRate*100.0)
  }
  fmt.Fprintf(&b, "  Total:\t%.4f %s\n", totalSec*mult, unitDisplay)
  if slowest == nil {
    fmt.Fprintf(&b, "  Slowest:\t-inf %s\n", unitDisplay)
  } else {
    fmt.Fprintf(&b, "  Slowest:\t%.4f %s\n", *slowest*mult, unitDisplay)
  }
  if fastest == nil {
    fmt.Fprintf(&b, "  Fastest:\tinf %s\n", unitDisplay)
  } else {
    fmt.Fprintf(&b, "  Fastest:\t%.4f %s\n", *fastest*mult, unitDisplay)
  }
  if average == nil {
    fmt.Fprintf(&b, "  Average:\tNaN %s\n", unitDisplay)
  } else {
    fmt.Fprintf(&b, "  Average:\t%.4f %s\n", *average*mult, unitDisplay)
  }
  fmt.Fprintf(&b, "  Requests/sec:\t%.4f\n", reqPerSec)
  b.WriteString("\n")
  b.WriteString("  Total data:\t" + formatBytes(totalData) + "\n")
  if sizePerReq == nil {
    b.WriteString("  Size/request:\tNaN\n")
  } else {
    // sizePerReq is float (totalData/successCount). Format via formatBytes? For integer values like 500.0, formatBytes(500) gives "500 B". For float 2.5? formatBytesFloat? Use formatBytesFloat for sizePerReq (since it may be fractional? Actually sizePerRequest for integer sizes is integer (500.0 -> "500 B"). Good. Use formatBytesFloat which handles float.
    b.WriteString("  Size/request:\t" + formatBytesFloat(*sizePerReq) + "\n")
  }
  b.WriteString("  Size/sec:\t" + formatBytesFloat(sizePerSec) + "\n")
  b.WriteString("\n")
  // Histogram
  b.WriteString("Response time histogram:\n")
  if len(durations) == 0 {
    for i := 0; i < 11; i++ {
      fmt.Fprintf(&b, "    NaN %s [0] |\n", unitDisplay)
    }
  } else {
    // histKeys are in seconds as strings (via FormatFloat 'g'), need to convert to unit for display with 3 decimals? Actually histKeys are bucket values in seconds (float). For display, convert to unit and format with 3 decimals, right-aligned width 7? As analyzed: "  %7.3f %s [%d] |%s" with count padding to maxLen and bars.
    // Parse histKeys back to float for conversion? Or recompute buckets in seconds and convert? histKeys are strings like "0.000697507" (seconds). Parse to float, convert to unit (*mult), format with 3 decimals.
    // Find maxCount for bars and count padding
    maxCount := 0
    for _, c := range histCounts {
      if c > maxCount {
        maxCount = c
      }
    }
    maxCountLen := len(fmt.Sprintf("[%d]", maxCount))
    for i, k := range histKeys {
      v, _ := strconv.ParseFloat(k, 64)
      dispVal := v * mult
      count := histCounts[i]
      // Bars: count*32/max (floor)? For max 0 (all zero? Actually with successes, max>0 (at least 1). Good. For no successes case already handled (len==0, NaN). Good. So max>0 here.
      bars := ""
      if maxCount > 0 && count > 0 {
        nBars := count * 32 / maxCount
        // For count>0 but nBars==0 (e.g., count 1, max 100, 32*1/100=0)? Should be at least 1? Original for count 1 with max 2251 (like -z 2s histogram: [1] with 1 bar? Actually earlier -z 2s histogram: "  0.303 ms [1]    |" with no bars? Wait that line had no bars (just | with no ■)? Actually "  0.303 ms [1]    |" (no bars shown? The line ends with | with no bars? In our earlier -z 2s output: "  0.303 ms [1]    |" (no bars). Hmm. For count 1 with max 2251, bars = 32*1/2251=0 (floor 0), so 0 bars (just |). Good. So 0 bars allowed for small counts (no minimum 1). Good. Implement floor, no minimum.
        bars = strings.Repeat("\u25a0", nBars)
      }
      countStr := fmt.Sprintf("[%d]", count)
      // Pad countStr to maxCountLen with spaces (left-aligned, i.e., countStr + spaces)
      for len(countStr) < maxCountLen {
        countStr += " "
      }
      fmt.Fprintf(&b, "  %7.3f %s %s |%s\n", dispVal, unitDisplay, countStr, bars)
    }
  }
  b.WriteString("\n")
  b.WriteString("Response time distribution:\n")
  pcts := []struct {
    label string
    val *float64
  }{
    {"10.00%", p10}, {"25.00%", p25}, {"50.00%", p50}, {"75.00%", p75}, {"90.00%", p90}, {"95.00%", p95}, {"99.00%", p99}, {"99.90%", p999}, {"99.99%", p9999},
  }
  for _, p := range pcts {
    if p.val == nil {
      fmt.Fprintf(&b, "  %s in NaN %s\n", p.label, unitDisplay)
