        if h, p, err := net.SplitHostPort(addr); err == nil {
          addrHostTrimmed := strings.Trim(h, "[]")
          reqHostTrimmed := strings.Trim(reqHost, "[]")
          if strings.EqualFold(reqHostTrimmed, addrHostTrimmed) && reqPort == p {
            tgt := tgtHost + ":" + tgtPort
            if strings.Contains(tgtHost, ":") && !strings.HasPrefix(tgtHost, "[") {
              tgt = "[" + tgtHost + "]:" + tgtPort
            }
            return baseDialer.DialContext(ctx, network, tgt)
          }
        }
      }
      return baseDialer.DialContext(ctx, network, addr)
    }
  } else {
    dialFunc = baseDialer.DialContext
  }
