    if len(cfg.ProxyHeaders) > 0 {
      h := make(http.Header)
      for _, ph := range cfg.ProxyHeaders {
        idx := strings.Index(ph, ":")
        name := ph[:idx]
        val := ph[idx+1:]
        for len(val) > 0 && val[0] == ' ' {
          val = val[1:]
        }
        h.Add(name, val)
      }
      tr.ProxyConnectHeader = h
    }
  }
  redirectLimit := cfg.Redirect
  client := &http.Client{
    Transport: tr,
    CheckRedirect: func(req *http.Request, via []*http.Request) error {
      if redirectLimit == 0 {
        return http.ErrUseLastResponse
      }
      if len(via) > redirectLimit {
        return fmt.Errorf("Redirection limit has reached")
      }
      if len(via) > 0 {
        last := via[len(via)-1]
        req.Method = last.Method
        if last.GetBody != nil {
          body, _ := last.GetBody()
          req.Body = body
          req.GetBody = last.GetBody
          req.ContentLength = last.ContentLength
        }
      }
      return nil
    },
  }
  return client, method, staticBody, staticFormCT, bodyLines, formBoundary
}
