func runFixedN_QPS(cfg *Config, singleURL string, fileURLs []string, randEscaped string) int {
  client, method, staticBody, staticFormCT, bodyLines, _ := setupH1Client(cfg)
  n := cfg.NRequests
  cNum := cfg.NConnections
  if cNum <= 0 {
    cNum = 1
    if n > 0 && cfg.NConnections == 0 {
      // -c 0 means 0 workers, 0 requests (as in basic path? Actually for QPS with -c 0, what? Original -c 0 -n 1 -q 10? With 0 workers, 0 requests (like basic). Good. Handle: if cfg.NConnections==0, results empty.
      startTime := time.Now()
      totalDur := time.Since(startTime)
      return outputResults(cfg, []ReqResult{}, totalDur, startTime)
    }
  }
  if n == 0 {
    startTime := time.Now()
    totalDur := time.Since(startTime)
    return outputResults(cfg, []ReqResult{}, totalDur, startTime)
  }
  qps := *cfg.QPS
  // Handle QPS <=0, Inf, NaN as no pacing (as fast as possible, same as without QPS)? As analyzed, -q 0 gives no pacing (fast). Good.
  if qps <= 0 || isInf(qps) || isNaN(qps) {
    // No pacing, run as fixed N without QPS (reuse basic path logic? For simplicity, call runLoadTestH1 basic? But that would recurse (since cfg.QPS != nil, it would dispatch to here again, infinite loop). Good. So handle here with same logic as basic (workers with atomic counter, no pacing).
    // Duplicate basic workers code here (without pacing).
    startTime := time.Now()
    var results []ReqResult
    var mu sync.Mutex
    var nextIdx int64 = -1
    var wg sync.WaitGroup
    for i := 0; i < cNum; i++ {
      wg.Add(1)
      go func() {
        defer wg.Done()
        for {
          idx := atomic.AddInt64(&nextIdx, 1)
          if int(idx) >= n {
            break
          }
          var urlStr string
          if cfg.UrlsFromFile {
            urlStr = fileURLs[randInt(len(fileURLs))]
